// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.13;

import {ISubAccounts} from "v2-core/src/interfaces/ISubAccounts.sol";
import {IManager} from "v2-core/src/interfaces/IManager.sol";

interface ISubAccountsManager {
  function WITHDRAW_COOLDOWN() external view returns (uint);

  function subAccounts() external view returns (ISubAccounts);

  function subAccountToOwner(uint) external view returns (address);

  function withdrawTimestamp(uint) external view returns (uint);

  function createSubAccount(IManager manager) external returns (uint accountId);

  /**
   * @notice Allows user to open an account by transferring their account NFT to this contract.
   * @dev User must approve contract first.
   * @param accountId The users' accountId
   */
  function depositSubAccount(uint accountId) external;

  /**
   * @notice Allows user to open an account for any address by transferring their own account NFT to this contract.
   */
  function depositSubAccountFor(uint accountId, address recipient) external;

  /**
   * @notice Activates the cooldown period to withdraw account.
   */
  function requestWithdrawAccount(uint accountId) external;

  /**
   * @notice Allows a user to complete their exit from the Matching system.
   * Can be called by anyone on withdrawable accounts.
   * @dev User must have previously called `requestWithdrawAccount()` and waited for the cooldown to elapse.
   * @param accountId The users' accountId
   */
  function completeWithdrawAccount(uint accountId) external;

  ////////////
  // Events //
  ////////////

  /**
   * @dev Emitted when a CLOB account is added to matching, or generated.
   */
  event DepositedSubAccount(uint indexed accountId, address indexed owner);

  /**
   * @dev Emitted when a CLOB account is closed.
   */
  event WithdrewSubAccount(uint indexed accountId);

  /**
   * @dev Emitted when a user requests account withdrawal and begins the cooldown
   */
  event WithdrawAccountCooldown(uint indexed accountId, address user);

  ////////////
  // Errors //
  ////////////
  error SAM_NotOwnerAddress();
  error SAM_AlreadyRequestedWithdraw();
  error SAM_CooldownNotStarted();
  error SAM_CooldownNotElapsed();
}

src/interfaces/ITradeModule.sol.content:
// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.13;

import {IBaseModule} from "./IBaseModule.sol";
import {IPerpAsset} from "v2-core/src/interfaces/IPerpAsset.sol";
import {IAsset} from "v2-core/src/interfaces/IAsset.sol";

interface ITradeModule is IBaseModule {
  struct OptionLimitOrder {
    uint subaccountId;
    address owner;
    uint nonce;
    TradeData data;
  }

  struct TradeData {
    address asset;
    uint subId;
    int limitPrice;
    int desiredAmount;
    // Fee per asset traded
    uint worstFee;
    // AccountId to receive the quoteAsset for ask order, or receive baseAsset for bid order
    uint recipientId;
    // True if this is an bid order
    bool isBid;
  }

  /**
   * @dev A "Fill" is a trade that occurs when a market is crossed. A single new order can result in multiple fills.
   * The taker is the account that is crossing the market. The makerAccounts are those with actions being filled.
   *
   * If the taker order is a bid;
   * the taker is sending the maker accounts quoteAsset, and receiving the baseAsset from the maker accounts.
   *
   * If the taker order is an ask;
   * the taker is sending the maker accounts baseAsset, and receiving the quoteAsset from the maker accounts.
   */

  struct OrderData {
    uint takerAccount;
    // total fee for taker
    uint takerFee;
    // maker details
    FillDetails[] fillDetails;
    bytes managerData;
  }

  struct FillDetails {
    uint filledAccount;
    uint amountFilled;
    // price per asset
    int price;
    // total fee for maker
    uint fee;
  }

  function quoteAsset() external view returns (IAsset);
  function isPerpAsset(IPerpAsset perpAsset) external view returns (bool);
  function feeRecipient() external view returns (uint);
  function filled(address owner, uint nonce) external view returns (uint);
  function seenNonces(address owner, uint nonce) external view returns (bytes32);
  function setFeeRecipient(uint _feeRecipient) external;
  function setPerpAsset(IPerpAsset _perpAsset, bool isPerp) external;

  error TM_InvalidActionsLength();
  error TM_SignedAccountMismatch();
  error TM_IsBidMismatch();
  error TM_InvalidRecipientId();
  error TM_InvalidNonce();
  error TM_FeeTooHigh();
  error TM_PriceTooHigh();
  error TM_PriceTooLow();
  error TM_FillLimitCrossed();
  error TM_AssetMismatch();
  error TM_AssetSubIdMismatch();

  event OrderMatched(address base, uint taker, uint maker, bool takerIsBid, int amtQuote, uint amtBase);
  event FeeCharged(uint acc, uint recipient, uint takerFee);
}

src/modules/BaseModule.sol.content:
// SPDX-License-Identifier: GPL-3.0-only
pragma solidity ^0.8.13;

// Inherited
import {IBaseModule} from "../interfaces/IBaseModule.sol";

// Interfaces
import {ISubAccounts} from "v2-core/src/interfaces/ISubAccounts.sol";
import {Ownable2Step} from "openzeppelin/access/Ownable2Step.sol";
import {IMatching} from "../interfaces/IMatching.sol";
import {IERC20} from "openzeppelin/token/ERC20/IERC20.sol";

/**
 * @title BaseModule
 * @dev Implement common utils shared by all modules
 */
abstract contract BaseModule is IBaseModule, Ownable2Step {
  IMatching public immutable matching;
  ISubAccounts public immutable subAccounts;

  mapping(address owner => mapping(uint nonce => bool used)) public usedNonces;

  constructor(IMatching _matching) {
    matching = _matching;
    subAccounts = _matching.subAccounts();
  }

  /**
   * @dev Module contracts should never hold any funds, but just in case, allow the owner to withdraw
   */
  function withdrawERC20(address token, address recipient, uint amount) external onlyOwner {
    IERC20(token).transfer(recipient, amount);
  }

  /**
   * @dev Return the subAccounts back to the matching address
   */
  function _returnAccounts(VerifiedAction[] memory actions, uint[] memory newAccIds) internal {
    for (uint i = 0; i < actions.length; ++i) {
      if (actions[i].subaccountId == 0) continue;
      if (subAccounts.ownerOf(actions[i].subaccountId) == address(matching)) continue;

      subAccounts.transferFrom(address(this), address(matching), actions[i].subaccountId);
    }
    for (uint i = 0; i < newAccIds.length; ++i) {
      subAccounts.transferFrom(address(this), address(matching), newAccIds[i]);
    }
  }

  /**
   * @dev Matching contract doesn't validate if nonce is re-used. This function checks and invalidates nonce in each modules.
   */
  function _checkAndInvalidateNonce(address owner, uint nonce) internal {
    if (usedNonces[owner][nonce]) revert BM_NonceAlreadyUsed();
    usedNonces[owner][nonce] = true;

    emit NonceUsed(owner, nonce);
  }

  ///////////////////
  //   Modifiers   //
  ///////////////////

  modifier onlyMatching() {
    if (msg.sender != address(matching)) revert BM_OnlyMatching();
    _;
  }
}
